import type { CacheEvent, CacheEventType } from '../engine/types.ts'

/**
 * Разбор событий стенда. Объяснения привязаны к ТИПУ события: какой бы
 * сценарий ни крутился, клик по «db.stampede» откроет один и тот же разбор,
 * подставив в него конкретные ключи и числа из payload.
 */

export interface Explanation {
  title: string
  body: string[]
  /** Как это выглядит в сервисе на Go. */
  go?: string
  model?: string
  terms: string[]
}

const num = (v: unknown) => (typeof v === 'number' ? v : Number(v ?? 0))
const str = (v: unknown) => (typeof v === 'string' ? v : String(v ?? ''))

function plural(n: number, one: string, few: string, many: string): string {
  const mod10 = n % 10
  const mod100 = n % 100
  if (mod10 === 1 && mod100 !== 11) return one
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few
  return many
}
const ticks = (n: number) => `${n} ${plural(n, 'тик', 'тика', 'тиков')}`
const keys = (n: number) => `${n} ${plural(n, 'ключ', 'ключа', 'ключей')}`
const reqs = (n: number) => `${n} ${plural(n, 'запрос', 'запроса', 'запросов')}`
const key = (v: unknown) => `k${num(v)}`

const INVALIDATION: Record<string, string> = {
  none: 'ничего не делать с кэшем при записи',
  delete: 'удалять ключ из кэша при записи',
  update: 'класть новое значение прямо в кэш',
}

type Explainer = (e: CacheEvent) => Explanation

const EXPLAIN: Record<CacheEventType, Explainer> = {
  'req.hit': (e) => ({
    title: `Попадание: ${key(e.payload.key)} нашёлся в кэше`,
    body: [
      'Ответ ушёл клиенту за тик, база об этом запросе ничего не узнала. Ради этого кэш и ставят: он превращает дорогое обращение к базе в дешёвое чтение из памяти.',
      'Каждое попадание — это ещё и запрос, который не встал в очередь к базе. Поэтому кэш влияет на задержку вдвойне: и напрямую, и через разгрузку базы.',
    ],
    terms: ['cache-hit-ratio'],
  }),

  'req.miss': (e) => ({
    title: `Промах: ${key(e.payload.key)} в кэше нет`,
    body: [
      e.payload.cached
        ? 'Значит, этот ключ либо ещё ни разу не спрашивали, либо его вытеснили более популярные, либо его запись истекла. Приложение идёт в базу и положит ответ в кэш — это cache-aside.'
        : 'Кэша нет вовсе: каждый запрос идёт в базу.',
      `В очереди к базе сейчас ${reqs(num(e.payload.queue))}. Промах стоит не только времени запроса, но и ожидания в этой очереди.`,
    ],
    go: 'v, err := rdb.Get(ctx, key).Result(); if errors.Is(err, redis.Nil) { v = loadFromDB(ctx); rdb.Set(ctx, key, v, ttl) }',
    terms: ['cache-aside', 'cache-hit-ratio'],
  }),

  'req.join': (e) => ({
    title: `${key(e.payload.key)}: запрос присоединился к уже летящему в базу`,
    body: [
      `За этим ключом уже идёт запрос, и новый промах не создаёт второго — он ждёт того же ответа. Сейчас ответа ждут ${num(e.payload.waiters)}.`,
      'Так работает объединение одинаковых запросов: сколько бы клиентов ни промахнулись по одному ключу одновременно, база получит один запрос.',
    ],
    go: 'golang.org/x/sync/singleflight: v, err, _ := g.Do(key, func() (any, error) { return loadFromDB(ctx) })',
    terms: ['singleflight', 'cache-stampede'],
  }),

  'req.stale': (e) => ({
    title: `${key(e.payload.key)}: отдано устаревшее значение (версия ${num(e.payload.cached)} против ${num(e.payload.db)} в базе)`,
    body: [
      `Запись лежит в кэше ${ticks(num(e.payload.age))}, и за это время значение в базе изменилось. Клиент получил старое — и не узнает об этом.`,
      e.payload.invalidation === 'none'
        ? 'Настройка «ничего не делать при записи»: кэш узнает о новом значении, только когда запись истечёт по TTL. Чем длиннее TTL, тем дольше живёт устаревшее.'
        : 'Инвалидация включена, но окно всё равно осталось: между записью в базу и удалением ключа проходит время, а иногда старое значение успевает вернуться в кэш после удаления.',
    ],
    terms: ['cache-invalidation'],
  }),

  'req.swr': (e) => ({
    title: `${key(e.payload.key)}: отдано просроченное значение, обновление идёт${e.payload.refreshing ? ' (уже запущено)' : ''}`,
    body: [
      `Запись просрочена ${ticks(num(e.payload.age))} назад, но клиент получил её мгновенно вместо ожидания базы. Свежее значение приедет в фоне и заменит её.`,
      'Так обменивают строгую свежесть на задержку: пользователь никогда не ждёт базу, а данные могут быть на TTL устаревшими. Для лент, счётчиков и витрин это почти всегда правильный обмен.',
    ],
    go: 'ответ отдаётся сразу, обновление — в отдельной горутине через singleflight; в HTTP это заголовок Cache-Control: stale-while-revalidate',
    terms: ['stale-while-revalidate', 'cache-stampede'],
  }),

  'db.done': (e) => ({
    title: `База ответила про ${key(e.payload.key)} за ${ticks(num(e.payload.service))}${num(e.payload.waiters) > 1 ? `, ответ получили ${num(e.payload.waiters)}` : ''}`,
    body: [
      e.payload.refresh
        ? 'Это фоновое обновление просроченной записи: ответ никто не ждал, он просто лёг в кэш.'
        : `Значение легло в кэш, и следующие запросы за этим ключом будут попаданиями — пока запись не вытеснят или она не истечёт.`,
      num(e.payload.waiters) > 1 ? 'Один запрос в базу обслужил сразу нескольких клиентов: они присоединились к нему, пока он летел.' : '',
    ].filter(Boolean),
    terms: ['cache-aside'],
  }),

  'write.done': (e) => ({
    title: `Запись в ${key(e.payload.key)}: версия ${num(e.payload.version)}`,
    body: [
      `Значение в базе изменилось. Настройка инвалидации — ${INVALIDATION[str(e.payload.invalidation)] ?? ''}.`,
      e.payload.invalidation === 'none'
        ? 'Кэш об этом не узнал: он продолжит отдавать старое значение до истечения TTL.'
        : e.payload.invalidation === 'delete'
          ? 'Ключ удалён из кэша: следующее чтение промахнётся и принесёт свежее значение. Это самый распространённый способ — он не зависит от того, что именно записали.'
          : 'Новое значение положено прямо в кэш: лишнего промаха не будет. Но так можно делать, только если приложение знает полное значение ключа после записи.',
    ],
    go: 'после успешного коммита: rdb.Del(ctx, key) — не до, иначе гонка почти гарантирована',
    terms: ['cache-invalidation'],
  }),

  'cache.expired': (e) => ({
    title: `${key(e.payload.key)}: запись истекла через ${ticks(num(e.payload.age))}`,
    body: [
      'TTL — главный способ не хранить в кэше мусор вечно и ограничить устаревание. Но у него есть цена: в момент истечения все, кто спросит этот ключ, промахнутся.',
      e.payload.swr
        ? 'Здесь включена отдача просроченного значения: клиенты получат старое сразу, а обновление пойдёт в фоне.'
        : e.payload.coalesce
          ? 'Объединение запросов включено: в базу уйдёт один запрос, остальные подождут его.'
          : 'Каждый промах пойдёт в базу отдельно — если ключ горячий, это лавина.',
    ],
    terms: ['cache-stampede'],
  }),

  'cache.flush': (e) => ({
    title: `Кэш опустел: потеряно ${keys(num(e.payload.entries))}`,
    body: [
      'Перезапуск Redis, переключение на новый кластер, выкатка с новым форматом ключей, полная инвалидация — способов остаться без кэша много.',
      'Теперь вся нагрузка идёт в базу, рассчитанную на её малую долю. И наполняться кэш будет ровно с той скоростью, с какой отвечает перегруженная база: это самоподдерживающееся состояние, из которого система может не выйти сама.',
    ],
    go: 'прогрев при старте, постепенный переход на новые ключи, ограничение параллельных походов в базу',
    terms: ['cache-warmup', 'metastable-failure'],
  }),

  'cache.warm': (e) => ({
    title: `Кэш прогрет: ${keys(num(e.payload.count))} положены заранее`,
    body: [
      'Прогрев спасает от холодного старта: сервис начинает работать с готовым кэшем, а не собирает его из промахов пользователей.',
      num(e.payload.jitter) > 0
        ? `TTL у всех записей — ${ticks(num(e.payload.ttl))} плюс случайная добавка до ${num(e.payload.jitter)}%: истекать они будут вразнобой.`
        : `Но TTL у всех одинаковый — ${ticks(num(e.payload.ttl))}. Значит, ровно через это время они истекут все разом, и база получит всплеск промахов.`,
    ],
    terms: ['cache-warmup', 'cache-stampede'],
  }),

  'cache.stale-set': (e) => ({
    title: `Гонка: в кэш легло старое значение ${key(e.payload.key)} (версия ${num(e.payload.cached)}, в базе ${num(e.payload.db)})`,
    body: [
      'Классическая гонка cache-aside. Чтение промахнулось и пошло в базу. Пока оно шло, другая транзакция записала новое значение и удалила ключ из кэша. А потом чтение вернулось и положило в кэш то, что прочитало, — уже устаревшее.',
      num(e.payload.ttl) > 0
        ? `Теперь кэш будет отдавать старое значение до истечения TTL — ${ticks(num(e.payload.ttl))}. Поэтому TTL ставят даже там, где есть инвалидация: он ограничивает ущерб от таких гонок.`
        : 'TTL нет, поэтому старое значение останется в кэше до следующей записи по этому ключу. Именно поэтому вечный кэш с инвалидацией — плохая идея.',
    ],
    go: 'ограничить ущерб: TTL всегда; убрать гонку: версии в ключе или запись в кэш через CAS/Lua-скрипт',
    terms: ['cache-invalidation', 'cache-aside'],
  }),

  'db.stampede': (e) => ({
    title: `Лавина: за ${key(e.payload.key)} в базу летит ${reqs(num(e.payload.inflight))} сразу`,
    body: [
      'Ключ истёк или был вытеснен, и все, кто спросил его, пока первый запрос ещё шёл, тоже пошли в базу — за одним и тем же значением. Чем горячее ключ и чем дольше запрос, тем больше таких дублей.',
      e.payload.coalesce
        ? 'Объединение включено — значит, эти запросы пришли за разными ключами или разными волнами.'
        : 'Лечится объединением одинаковых запросов (singleflight), отдачей просроченного значения или блокировкой на обновление ключа.',
    ],
    go: 'singleflight.Group на ключ кэша — и в базу уйдёт ровно один запрос',
    terms: ['cache-stampede', 'singleflight'],
  }),

  'db.queue': (e) => ({
    title: `Очередь в базе: ${reqs(num(e.payload.len))}`,
    body: [
      `База успевает ${num(e.payload.capacity).toFixed(2)} запроса за тик. Промахов сейчас больше — очередь растёт, и каждый промах ждёт дольше предыдущего.`,
      `В кэше ${keys(num(e.payload.cached))}. Пока он не наполнится, нагрузка на базу не упадёт — а наполняется он ответами той же перегруженной базы.`,
    ],
    terms: ['utilization', 'cache-warmup'],
  }),

  'db.drained': (e) => ({
    title: 'Очередь в базе разошлась',
    body: [`В кэше ${keys(num(e.payload.cached))}, промахи снова редкие, и база успевает отвечать без очереди.`],
    terms: ['cache-hit-ratio'],
  }),

  'load.change': (e) => ({
    title: num(e.payload.to) > num(e.payload.from) ? `Нагрузка выросла в ${num(e.payload.to)} раза` : 'Нагрузка вернулась к обычной',
    body: [`Теперь приходит ${num(e.payload.rate).toFixed(1)} запроса за тик. Для базы важно не это число, а доля промахов от него.`],
    terms: ['cache-hit-ratio'],
  }),
}

export function explain(e: CacheEvent): Explanation {
  return EXPLAIN[e.type](e)
}
